import{_ as t,o as e,c as d,a5 as i}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"Java 知识库","description":"这套内容面向已经掌握 Java 基本语法、希望理解 Java 后端系统如何运行并能排查线上问题的开发者。页面以原理讲解为主，同时保留可执行的命令、配置和故障案例。","frontmatter":{},"headers":[],"relativePath":"java/index.md","filePath":"java/index.md"}'),l={name:"java/index.md"};function r(s,a,n,c,f,o){return e(),d("div",null,[...a[0]||(a[0]=[i('<h1 id="java-知识库" tabindex="-1" data-src-line="1" data-src-file="java/index.md">Java 知识库 <a class="header-anchor" href="#java-知识库" aria-label="Permalink to &quot;Java 知识库&quot;">​</a></h1><p data-src-line="3" data-src-file="java/index.md">这套内容面向已经掌握 Java 基本语法、希望理解 Java 后端系统如何运行并能排查线上问题的开发者。页面以原理讲解为主，同时保留可执行的命令、配置和故障案例。</p><h2 id="内容地图" tabindex="-1" data-src-line="5" data-src-file="java/index.md">内容地图 <a class="header-anchor" href="#内容地图" aria-label="Permalink to &quot;内容地图&quot;">​</a></h2><ul data-src-line="7" data-src-file="java/index.md"><li data-src-line="7" data-src-file="java/index.md"><strong><a href="./01-java-language/chapter-01-why-java.html">01 Java 语言核心</a></strong>：类型、对象语义、面向对象、泛型、注解、Lambda、异常、集合、Stream，以及 record、sealed 与模式匹配特性。</li><li data-src-line="8" data-src-file="java/index.md"><strong><a href="./02-jvm-runtime/chapter-01-bytecode-classloading.html">02 JVM 运行时</a></strong>：字节码、类加载、运行时数据区、对象布局、GC、JIT 与堆外内存。</li><li data-src-line="9" data-src-file="java/index.md"><strong><a href="./03-java-concurrency/chapter-01-why-concurrency.html">03 Java 并发</a></strong>：内存模型、同步原语、并发工具、线程池、异步模型与虚拟线程。</li><li data-src-line="10" data-src-file="java/index.md"><strong><a href="./04-java-network/chapter-01-network-basics.html">04 Java 网络</a></strong>：网络基础、Socket/NIO、Netty、HTTP、Servlet/Tomcat、RPC 与长连接协议。</li><li data-src-line="11" data-src-file="java/index.md"><strong><a href="./05-java-data-access/chapter-01-persistence-thought.html">05 Java 数据访问</a></strong>：持久化思想、JDBC、连接池、MyBatis、ORM 与性能优化。</li><li data-src-line="12" data-src-file="java/index.md"><strong><a href="./06-diagnostics/">06 诊断</a></strong>：按故障域组织 JVM、并发、网络与数据访问的排查流程与生产案例。</li></ul><p data-src-line="14" data-src-file="java/index.md">下面的三条入口索引同一批内容，但面向不同的阅读目标。</p><h2 id="入口-a-按知识体系学习" tabindex="-1" data-src-line="16" data-src-file="java/index.md">入口 A：按知识体系学习 <a class="header-anchor" href="#入口-a-按知识体系学习" aria-label="Permalink to &quot;入口 A：按知识体系学习&quot;">​</a></h2><p data-src-line="18" data-src-file="java/index.md">适合系统学习，从语言机制逐步深入到运行与排障。</p><ol data-src-line="20" data-src-file="java/index.md"><li data-src-line="20" data-src-file="java/index.md">完成 Java 语言核心：类型、对象语义、面向对象、泛型、注解、Lambda、异常、集合、Stream/Optional 和现代语言特性。</li><li data-src-line="21" data-src-file="java/index.md">沿字节码、运行时数据区、对象布局、GC、JIT 和堆外内存理解执行过程。</li><li data-src-line="22" data-src-file="java/index.md">学习 Java 内存模型、同步机制和并发工具。</li><li data-src-line="23" data-src-file="java/index.md">根据工作方向进入网络通信或数据访问。</li><li data-src-line="24" data-src-file="java/index.md">最后通过诊断方法与生产案例串联前面的机制。</li></ol><h2 id="入口-b-按故障现象排查" tabindex="-1" data-src-line="26" data-src-file="java/index.md">入口 B：按故障现象排查 <a class="header-anchor" href="#入口-b-按故障现象排查" aria-label="Permalink to &quot;入口 B：按故障现象排查&quot;">​</a></h2><p data-src-line="28" data-src-file="java/index.md">适合线上问题，从症状出发，而不是直接判断根因属于哪个技术域。</p><table tabindex="0"><thead data-src-line="30" data-src-file="java/index.md"><tr data-src-line="30" data-src-file="java/index.md"><th style="text-align:left;">你看到的现象</th><th style="text-align:left;">先去的入口</th></tr></thead><tbody data-src-line="32" data-src-file="java/index.md"><tr data-src-line="32" data-src-file="java/index.md"><td style="text-align:left;">CPU 利用率高、计算繁忙</td><td style="text-align:left;"><a href="./06-diagnostics/01-jvm/chapter-01-jvm-diagnostics.html">JVM 诊断</a> 与 <a href="./06-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.html">并发诊断</a></td></tr><tr data-src-line="33" data-src-file="java/index.md"><td style="text-align:left;">堆内存持续增长、OOM、Metaspace 增长</td><td style="text-align:left;"><a href="./06-diagnostics/01-jvm/chapter-02-cases-cpu-memory.html">JVM 内存与 GC 案例</a></td></tr><tr data-src-line="34" data-src-file="java/index.md"><td style="text-align:left;">GC 频繁、停顿长、吞吐下降</td><td style="text-align:left;"><a href="./06-diagnostics/01-jvm/chapter-03-cases-gc-resources.html">GC 案例</a> 与 <a href="./06-diagnostics/01-jvm/chapter-04-cases-gc-latency.html">GC 延迟案例</a></td></tr><tr data-src-line="35" data-src-file="java/index.md"><td style="text-align:left;">死锁、锁竞争、线程池饱和、异步超时</td><td style="text-align:left;"><a href="./06-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.html">并发诊断</a></td></tr><tr data-src-line="36" data-src-file="java/index.md"><td style="text-align:left;">接口超时、RT 高、连接失败、连接数异常</td><td style="text-align:left;"><a href="./06-diagnostics/03-network/chapter-01-network-diagnostics.html">网络诊断</a></td></tr><tr data-src-line="37" data-src-file="java/index.md"><td style="text-align:left;">获取连接超时、连接池耗尽、慢 SQL</td><td style="text-align:left;"><a href="./06-diagnostics/04-data-access/">数据访问诊断</a></td></tr><tr data-src-line="38" data-src-file="java/index.md"><td style="text-align:left;">容器 OOMKilled、堆外内存异常</td><td style="text-align:left;"><a href="./06-diagnostics/01-jvm/chapter-05-cases-offheap-network.html">堆外与网络案例</a></td></tr></tbody></table><p data-src-line="40" data-src-file="java/index.md">进入后对照相似案例确定第一步采集什么数据，再回到对应原理章节验证根因，而不是只复制修复参数。完整的跨域定位路径见 <a href="./06-diagnostics/">诊断总览</a>。</p><h2 id="入口-c-按工具与证据查阅" tabindex="-1" data-src-line="42" data-src-file="java/index.md">入口 C：按工具与证据查阅 <a class="header-anchor" href="#入口-c-按工具与证据查阅" aria-label="Permalink to &quot;入口 C：按工具与证据查阅&quot;">​</a></h2><p data-src-line="44" data-src-file="java/index.md">适合你已经拿到了现场证据，需要判断它证明了什么、下一步去哪。</p><table tabindex="0"><thead data-src-line="46" data-src-file="java/index.md"><tr data-src-line="46" data-src-file="java/index.md"><th style="text-align:left;">你手上的证据</th><th style="text-align:left;">能证明什么、去哪查</th></tr></thead><tbody data-src-line="48" data-src-file="java/index.md"><tr data-src-line="48" data-src-file="java/index.md"><td style="text-align:left;">线程转储（jstack/Arthas）</td><td style="text-align:left;">线程状态、锁持有、调用栈。去 <a href="./06-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.html">并发诊断</a>。</td></tr><tr data-src-line="49" data-src-file="java/index.md"><td style="text-align:left;">JFR / GC 日志</td><td style="text-align:left;">分配速率、GC 原因与停顿、SafePoint。去 <a href="./06-diagnostics/01-jvm/chapter-01-jvm-diagnostics.html">JVM 诊断</a>。</td></tr><tr data-src-line="50" data-src-file="java/index.md"><td style="text-align:left;">堆转储（jmap/Arthas heapdump）</td><td style="text-align:left;">对象占用、泄漏点。去 <a href="./06-diagnostics/01-jvm/chapter-02-cases-cpu-memory.html">JVM 内存与 GC 案例</a>。</td></tr><tr data-src-line="51" data-src-file="java/index.md"><td style="text-align:left;">抓包（tcpdump/Wireshark）</td><td style="text-align:left;">建连、重传、RTT、连接状态。去 <a href="./06-diagnostics/03-network/chapter-01-network-diagnostics.html">网络诊断</a>。</td></tr><tr data-src-line="52" data-src-file="java/index.md"><td style="text-align:left;">连接池指标（活跃数、等待时间）</td><td style="text-align:left;">连接供给与持有关系。去 <a href="./06-diagnostics/04-data-access/">数据访问诊断</a> 与 <a href="./06-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.html">并发诊断</a>。</td></tr><tr data-src-line="53" data-src-file="java/index.md"><td style="text-align:left;">Arthas 在线诊断</td><td style="text-align:left;">方法耗时、调用链、类加载。可同时对照 JVM 与并发诊断。</td></tr></tbody></table><p data-src-line="55" data-src-file="java/index.md">每条证据都先回答「证据指向哪一层」，再进入对应原理页，不要凭单一指标直接下结论。</p><h2 id="内容边界" tabindex="-1" data-src-line="57" data-src-file="java/index.md">内容边界 <a class="header-anchor" href="#内容边界" aria-label="Permalink to &quot;内容边界&quot;">​</a></h2><ul data-src-line="59" data-src-file="java/index.md"><li data-src-line="59" data-src-file="java/index.md">Java 专题解释语言、JVM、并发、网络和数据访问的底层机制。</li><li data-src-line="60" data-src-file="java/index.md">JPMS 模块系统属于语言与部署边界，只在现代语言特性页说明定位，不扩展成独立主线章节。</li><li data-src-line="61" data-src-file="java/index.md">Spring 专题负责框架配置、API 和集成方式。</li><li data-src-line="62" data-src-file="java/index.md">工程专题负责设计原则、架构和通用工程实践。</li><li data-src-line="63" data-src-file="java/index.md">MySQL、PostgreSQL 等专题负责数据库内核与 SQL 优化。</li></ul><p data-src-line="65" data-src-file="java/index.md">遇到跨专题问题时，各页面会给出下一跳链接，避免重复解释同一机制。</p>',19)])])}const x=t(l,[["render",r]]);export{m as __pageData,x as default};
